/bin/zsh -lc "node --test test/quantity.test.js && node --input-type=module <<'NODE'
import { writeFileSync } from 'node:fs';
import { lineFromRequest } from './src/api.js';

const zero_result = lineFromRequest({ sku: ' A ', quantity: '0' });
let error_message;
try {
  lineFromRequest({ sku: ' A ', quantity: '' });
} catch (error) {
  error_message = error.message;
}
if (error_message "'!== '"'invalid quantity') throw new Error('invalid input was not rejected as expected');
const answer = { changed_file: 'src/quantity.js', zero_result, error_message };
writeFileSync('answer.json', "'`${JSON.stringify(answer, null, 2)}'"\\n"'`);
console.log(JSON.stringify(answer));
NODE'

